import{_ as e,a0 as i,w as r,s as a,ao as p,I as n,x as u,a1 as s,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"Ubuntu 有了一个“怪怪的”新标志 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 有了一个“怪怪的”新标志 | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 有了一个“怪怪的”新标志 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 有了一个“怪怪的”新标志 | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20220317 Ubuntu has a ‘Weird Looking- New Logo","title":"Ubuntu 有了一个“怪怪的”新标志","tag":"202203","desc":""},"relativePath":"202203/20220317 Ubuntu has a ‘Weird Looking- New Logo.md","filePath":"[post].md"}'),b={name:"202203/20220317 Ubuntu has a ‘Weird Looking- New Logo.md"};function m(d,t,f,g,w,U){const o=i("Link");return r(),a("div",null,[t[22]||(t[22]=p('<h1 id="ubuntu-有了一个-怪怪的-新标志" tabindex="-1">Ubuntu 有了一个“怪怪的”新标志 <a class="header-anchor" href="#ubuntu-有了一个-怪怪的-新标志" aria-label="Permalink to “Ubuntu 有了一个“怪怪的”新标志”">​</a></h1><blockquote><p>Ubuntu 已经重新设计了它的标志。不是每个人都会喜欢它。</p></blockquote><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/03/ubuntu-unveils-new-logo.png?w=1200&amp;ssl=1" alt=""></p><p>Ubuntu 的标志包含了多个元素。对粉丝来说，橙色和紫色是 Ubuntu 的特征。</p><p>除此之外，Ubuntu 的标志上还写有 “ubuntu” 的字样，以及一个橙色的图案。</p><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/03/ubuntu-old-logo.png?w=1294&amp;ssl=1" alt="Ubuntu’s old logo"></p><p>这个橙色的“<ruby>朋友圈<rt>circle of friends</rt></ruby>”图案是 Ubuntu 的身份标识，它象征着：自由、协作、精确和可靠。</p><p>这个图案实际上是三个朋友或团队成员“搭在一起”的一个俯视图。你可能在体育运动中见到过这样的画面。</p><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/03/huddle.jpg?w=800&amp;ssl=1" alt="Image courtesy: Unsplash"></p><h3 id="ubuntu-有了一个全新的标志" tabindex="-1">Ubuntu 有了一个全新的标志 <a class="header-anchor" href="#ubuntu-有了一个全新的标志" aria-label="Permalink to “Ubuntu 有了一个全新的标志”">​</a></h3>',10)),n("p",null,[t[1]||(t[1]=u("但这个图案正在发生变化。",-1)),s(o,{href:"https://www.omgubuntu.co.uk/2022/03/ubuntu-has-a-brand-new-logo"},{default:l(()=>[...t[0]||(t[0]=[u("OMG! Ubuntu",-1)])]),_:1}),t[2]||(t[2]=u(" 报道说，Canonical 重新设计了标志的元素、文字和这个“朋友圈”的图案。",-1))]),t[23]||(t[23]=n("p",null,"在旧的标志中，“朋友圈”图案在粗体 “ubuntu” 文字的右上角。",-1)),t[24]||(t[24]=n("p",null,"新的标志改变了这一点。“朋友圈”图案经过重新设计，看起来更平滑，而且被放置在一个橙色的矩形里。文字也有变化，现在使用了更细的字体。“Ubuntu” 中的 “U” 现在是大写的了。",-1)),t[25]||(t[25]=n("p",null,"有趣的是，新标志不再包含注册商标符号 “®” 了。",-1)),t[26]||(t[26]=n("p",null,[n("img",{src:"https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/03/new-ubuntu-logo.png?w=780&ssl=1",alt:""})],-1)),n("p",null,[t[4]||(t[4]=u("Ubuntu 在官方博文中提到了关于新设计的 ",-1)),s(o,{href:"https://ubuntu.com/blog/a-new-look-for-the-circle-of-friends"},{default:l(()=>[...t[3]||(t[3]=[u("这些变化",-1)])]),_:1}),t[5]||(t[5]=u("：",-1))]),t[27]||(t[27]=n("blockquote",null,[n("p",null,"虽然（在设计上）和之前的朋友圈图案保持相对延续性很重要，但是更新后的版本更精简、更专注、更成熟。现在他们的头部在圆圈里，彼此面对，连接也更加直接，这看起来更合理一些。")],-1)),t[28]||(t[28]=n("p",null,"你可以在这个视频中看到新标志的动画：",-1)),n("p",null,[s(o,{href:"https://img.linux.net.cn/static/video/Ubuntu%20new%20logo%20animation-9DHUyz54flA.mp4"},{default:l(()=>[...t[6]||(t[6]=[n("img",{src:"https://i0.wp.com/i.ytimg.com/vi/9DHUyz54flA/hqdefault.jpg?w=780&ssl=1",alt:""},null,-1)])]),_:1})]),t[29]||(t[29]=p('<p>这个新标志将会出现在 Ubuntu 22.04 发行版中。</p><h3 id="这不是首次重新设计标志" tabindex="-1">这不是首次重新设计标志 <a class="header-anchor" href="#这不是首次重新设计标志" aria-label="Permalink to “这不是首次重新设计标志”">​</a></h3><p>这并不是 Ubuntu 第一次重新设计它的标志。早在 Ubuntu 项目于 2004 年初创时，“朋友圈”图案有三种颜色：黄色、红色和橙色。在 2010 年的时候，它被重新设计，“搭在一起的人” 变成了白色，他们被一个橙色的圆圈围绕着。</p><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/03/ubuntu-logo-comparison.jpg?w=1200&amp;ssl=1" alt="Image courtesy: OMG! Ubuntu"></p><h3 id="你喜欢这个新标志吗" tabindex="-1">你喜欢这个新标志吗？ <a class="header-anchor" href="#你喜欢这个新标志吗" aria-label="Permalink to “你喜欢这个新标志吗？”">​</a></h3><p>这次的新设计距离上一次已经过了 13 年。这个新“朋友圈”图案看起来还不错，但我还是觉得这个矩形背景有点怪怪的。</p><p>你怎么看？你喜欢 Ubuntu 的新标志吗，还是说更喜欢以前的那个呢？请在下方评论区分享你的观点吧！</p><hr>',8)),n("p",null,[t[8]||(t[8]=u("via: ",-1)),s(o,{href:"https://news.itsfoss.com/ubuntu-new-logo/"},{default:l(()=>[...t[7]||(t[7]=[u("https://news.itsfoss.com/ubuntu-new-logo/",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=u("作者：",-1)),s(o,{href:"https://news.itsfoss.com/author/root/"},{default:l(()=>[...t[9]||(t[9]=[u("Abhishek",-1)])]),_:1}),t[14]||(t[14]=u(" 选题：",-1)),s(o,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[10]||(t[10]=[u("lujun9972",-1)])]),_:1}),t[15]||(t[15]=u(" 译者：",-1)),s(o,{href:"https://github.com/lkxed"},{default:l(()=>[...t[11]||(t[11]=[u("lkxed",-1)])]),_:1}),t[16]||(t[16]=u(" 校对：",-1)),s(o,{href:"https://github.com/wxy"},{default:l(()=>[...t[12]||(t[12]=[u("wxy",-1)])]),_:1})]),n("p",null,[t[19]||(t[19]=u("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[17]||(t[17]=[u("LCTT",-1)])]),_:1}),t[20]||(t[20]=u(" 原创编译，",-1)),s(o,{href:"https://linux.cn/"},{default:l(()=>[...t[18]||(t[18]=[u("Linux中国",-1)])]),_:1}),t[21]||(t[21]=u(" 荣誉推出",-1))])])}const C=e(b,[["render",m]]);export{x as __pageData,C as default};
